SELECT 'gongkao', '奇偶位置限制', 'kp-pc-sl-parity-pos', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "奇偶位置限制"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不仅排人，连坑位都分出了奇偶。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“5 个人排队，甲乙必须站在奇数位上（第1, 3, 5个位置）”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把坑位当成一种特殊资源来抢："}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "先挑坑：在所有的奇数坑位里，挑出 2 个坑给甲乙。C(3, 2)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "甲乙落座：甲乙在这两个坑里全排列。A(2, 2)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "剩余人填坑：剩下的人在剩下的坑里全排列。A(3, 3)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "总计：C(3,2) × A(2,2) × A(3,3)。"}]}]}]}]}$$ AS jsonb), NULL, '奇偶位置限制的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "奇偶位置限制"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_sl_parity_pos", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
